}

::deep .unread-badge {
    position: absolute;
    top: 0.5rem;
    right: 0.75rem;
    background: #f23f43;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    border-radius: 9999px;
    padding: 0.1rem 0.4rem;
    min-width: 1rem;
    text-align: center;
}

/* Main message area */
.chat-main {
    display: flex;
    flex-direction: column;
    background: #313338;
    color: #f2f3f5;
    overflow: hidden;
}

::deep .message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
}

::deep .message-area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    flex-shrink: 0;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
}

::deep .message-area-header p {
    margin: 0.25rem 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
}

::deep .message-item {
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    position: relative;
    margin-bottom: 0.25rem;
}

::deep .message-item:hover {
    background: #2e3035;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

::deep .message-author {
    font-weight: 600;
    font-size: 0.9rem;
}

::deep .message-time {
    font-size: 0.7rem;
    color: #949ba4;
}

::deep .message-content {
    margin-top: 0.2rem;
    font-size: 0.9rem;
    line-height: 1.4;
}

::deep .message-reactions {
    display: flex;
    gap: 0.35rem;
    margin-top: 0.35rem;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #3f4147;
    border: 1px solid #4e5058;
    border-radius: 4px;
    padding: 0.15rem 0.4rem;
    font-size: 0.8rem;
    cursor: pointer;
}

::deep .reaction-badge:hover {
    border-color: #949ba4;
}

::deep .thread-link {
    background: none;
    border: none;
    color: #00a8fc;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.2rem 0;
    margin-top: 0.2rem;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 0.2rem;
}

::deep .action-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 0.75rem;
    cursor: pointer;
    padding: 0.2rem 0.4rem;
    border-radius: 3px;
}

::deep .action-btn:hover {
    background: #3f4147;
    color: #f2f3f5;
}

::deep .emoji-picker {
    display: flex;
    gap: 0.25rem;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 6px;
    padding: 0.4rem;
    margin-top: 0.3rem;
    width: fit-content;
}

::deep .emoji-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.2rem;
    border-radius: 4px;
}

::deep .emoji-btn:hover {
    background: #3f4147;
}

::deep .message-input-area,
::deep .thread-input-area {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border-top: 1px solid #3f4147;
    flex-shrink: 0;
}

::deep .message-input,
::deep .thread-input {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    padding: 0.6rem 0.75rem;
    color: #f2f3f5;
    font-size: 0.9rem;
    resize: none;
    min-height: 2.5rem;
    max-height: 8rem;
    font-family: inherit;
}

::deep .message-input:focus,
::deep .thread-input:focus {
    outline: none;
    box-shadow: 0 0 0 2px #5865f2;
}

::deep .send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 0.5rem 1rem;
    font-weight: 600;
    cursor: pointer;
    align-self: flex-end;
}

::deep .send-btn:hover:not(:disabled) {
    background: #4752c4;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread panel */
.chat-thread {
    background: #2b2d31;
    color: #f2f3f5;
    border-left: 1px solid #1e1f22;
    overflow: hidden;
}

::deep .thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
}

::deep .thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    flex-shrink: 0;
}

::deep .thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

::deep .close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.25rem;
    border-radius: 4px;
}

::deep .close-btn:hover {
    background: #3f4147;
    color: #f2f3f5;
}

::deep .thread-root-message {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    background: #232428;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1rem;
}

::deep .thread-reply {
    padding: 0.4rem 0;
    margin-bottom: 0.5rem;
}

/* Loading and empty states */
::deep .loading-indicator {
    text-align: center;
    padding: 0.75rem;
    color: #949ba4;
    font-size: 0.85rem;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #949ba4;
}

